def get_median(arr1, arr2, n):
    def find_kth_smallest(arr1, arr2, k):
        # Base cases
        if not arr1:
            return arr2[k-1]
        if not arr2:
            return arr1[k-1]
        if k == 1:
            return min(arr1[0], arr2[0])

        # Partition sizes
        partition_size = k // 2
        if partition_size > len(arr1):
            partition_size = len(arr1)

        # Partition elements
        partition_elem1 = arr1[partition_size - 1]
        partition_elem2 = arr2[partition_size - 1]

        # Count elements less than or equal to partition elements
        less_in_arr1 = sum(1 for x in arr1 if x <= partition_elem2)
        less_in_arr2 = sum(1 for x in arr2 if x <= partition_elem1)
        total_less = less_in_arr1 + less_in_arr2

        # Determine which partition is correct
        if total_less == k - 1:
            return max(partition_elem1, partition_elem2)
        elif total_less < k - 1:
            new_arr1 = [x for x in arr1 if x > partition_elem2]
            new_arr2 = [x for x in arr2 if x > partition_elem1]
            return find_kth_smallest(new_arr1, new_arr2, k - total_less - 1)
        else:
            new_arr1 = [x for x in arr1 if x <= partition_elem2]
            new_arr2 = [x for x in arr2 if x <= partition_elem1]
            return find_kth_smallest(new_arr1, new_arr2, k - total_less - 1)

    if n % 2 == 1:
        return find_kth_smallest(arr1, arr2, (n // 2) + 1)
    else:
        kth1 = find_kth_smallest(arr1, arr2, n // 2)
        kth2 = find_kth_smallest(arr1, arr2, n // 2 + 1)
        return (kth1 + kth2) / 2.0
